function pausedSession(value, seconds) {
  if (value?.status !== "paused") return {};
  const remaining = Number(value.remaining_ms);
  if (!Number.isFinite(remaining) || remaining < 0 || remaining > seconds * 1e3) return {};
  return { session: {
    version: 1,
    status: "paused",
    remaining_ms: remaining,
    paused_at: Number.isFinite(value.paused_at) ? value.paused_at : Date.now()
  } };
}
