  if(file) {headers.set('Content-Type',file.format==='pdf'?'application/pdf':'application/x-hwp');headers.set('Content-Disposition','attachment; filename="'+path.slice('/other-exams/download/'.length)+'.'+file.format+'"; filename*=UTF-8\x27\x27'+encodeURIComponent(file.filename));}
